/**
 * The shipped set, in increasing ink. Assigning in order gives the lightest
 * texture to the first owner.
 *
 * Six rather than nine: the three held back measured as not separable from
 * these at map size, whatever they look like in a swatch.
 */
export const SIGIL_PATTERN_SET = ["dot","stipple","hatch-right","hatch-left","crosshatch","scale"]

/**
 * How strongly to draw the ink over a region's fill.
 *
 * Coverage says how much ink there is, not how loud it is: at full strength
 * these compete with the borders and labels they are meant to support. Use
 * `assertive` where the pattern is doing the identifying (high contrast, or
 * colour otherwise unavailable) and `subtle` where colour already carries it.
 */
export const SIGIL_INK_OPACITY = {"assertive":0.45,"subtle":0.28}

/**
 * Build the <defs> content for a tier.
 *
 * @param tier          'lod2' | 'lod1' | 'lod0' — the same names the atlas uses
 * @param pxPerMapUnit  screen pixels per map unit at the current view, i.e.
 *                      (viewport width in px) / (viewBox width in map units).
 *                      This is what keeps density fixed in SCREEN space while
 *                      the map zooms; without it the texture would scale with
 *                      the map and be wrong at both ends of the ladder.
 * @param ids           which textures to define; defaults to the shipped set
 * @param prefix        id prefix, so several consumers can coexist on one page
 */
export function patternDefs(tier, pxPerMapUnit, ids = SIGIL_PATTERN_SET, prefix = 'sig') {
  const k = 1 / (pxPerMapUnit || 1)
  return ids
    .map((id) => {
      const spec = SIGIL_PATTERNS[id] && SIGIL_PATTERNS[id][tier]
      if (!spec) return ''
      const size = spec.period * k
      return (
        '<pattern id="' + prefix + '-' + id + '" width="' + size.toFixed(3) +
        '" height="' + size.toFixed(3) + '" patternUnits="userSpaceOnUse"' +
        ' patternTransform="rotate(' + spec.angle + ')">' +
        '<g transform="scale(' + k.toFixed(5) + ')">' + spec.tile + '</g></pattern>'
      )
    })
    .join('')
}

/** The fill value for a region, matching an id minted by `patternDefs`. */
export function patternFill(id, prefix = 'sig') {
  return 'url(#' + prefix + '-' + id + ')'
}
